package com.darkfleet.common.model;

import java.time.Instant;
import java.time.LocalDate;
import java.util.List;

/**
 * Daily intelligence brief generated by the DarkFleet agent summarizing notable activity
 * across the Baltic (Gulf of Finland -> Danish Straits) and Bosphorus / Black Sea corridors.
 */
public record DailyCorridorBrief(
        String briefId,
        LocalDate briefDate,
        String headline,
        String balticCorridorSummary,
        String bosphorusCorridorSummary,
        int candidateEventsInvestigated,
        int proposalsSubmitted,
        int coverageGapsSuppressed,
        List<String> keyHighlights,
        Instant generatedAt
) {
}
